test('both worker engine routes use broker credentials, actual upstream accounting and durable history',async t=>{for(const engine of ['hermes','opencode']){const r=rig(t),{EventEmitter}=require('events'),bus=new EventEmitter(),original=global.fetch;let generated=0,override;global.fetch=async(url,opts)=>String(url).startsWith('http://127.0.0.1:')?original(url,opts):response(String(url).endsWith('countTokens')?{totalTokens:5}:(generated++,reply()));const native={brokerProtocol:1,preflight:async()=>({ok:true}),runTask:async(_agent,_task,o)=>{override=o.cfgOverride;const result=await original(override.workerBaseUrl+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+override.workerApiKey,'Content-Type':'application/json'},body:JSON.stringify({model:override.workerModel,messages:[{role:'user',content:'Worker goal'}]})});assert.equal(result.status,200);return (await result.json()).choices[0].message.content;}};const workers=require('../lib/workers').createWorkers({home:r.home,bus,getCfg:()=>config({engine,nativeContinuity:true}),tools:{decide:()=>({level:'ask'})},gemini:{},[engine]:native});try{const done=new Promise(res=>bus.once('job:done',res)),j=workers.dispatch('alex','Goal');await done;const saved=r.home.findJob(j.id);assert.equal(saved.status,'review',saved.error);assert.equal(generated,1);assert.equal(override.workerProvider,'custom');assert.equal(saved.tokenBudget.measuredInput,5);assert.ok(saved.nativeBridge);}finally{workers.cancelAll();global.fetch=original;}}});
