test('crash between child creation and binding repairs budget/history/plan together before any enqueue',t=>{const r=rig(t),planner=require('../lib/project-plan').createPlanner({home:r.home,dispatch:()=>{},bus:null}),plan=planner.create({goal:'Goal',steps:[{id:'a',task:'Task',role:'Developer',agent:'alex'}]}),old=r.home.createJob('alex','Goal',{contract:{projectBinding:{projectId:plan.id,stepId:'a'}}});const file=r.home.p('projects',plan.id+'.json'),p=JSON.parse(fs.readFileSync(file));p.steps[0].jobId=old.id;require('../lib/job-storage').atomicWrite(file,p);r.home.updateJob('alex',old.id,{status:'failed',tokenBudget:require('../lib/job-budget').createBudget(config(),()=>{}).snapshot(),nativeBridge:r.storage.seal({version:1,jobId:old.id,actor:'alex',messages:[],parts:{}}),jobDecisions:[{origin:'human_main_window',historicalOnly:true}]});const source=r.home.findJob(old.id);r.home.updateJob('alex',old.id,{status:'retrying',retryIntent:{version:1,carry:require('../lib/job-retry').carry(source)}});const child=r.home.createJob('alex','Continue',{retryOf:old.id});r.home.recoverJobs();const repaired=r.home.findJob(child.id);assert.equal(repaired.retryLinkReady,true);assert.deepEqual(repaired.tokenBudget,source.tokenBudget);assert.deepEqual(repaired.nativeBridge,source.nativeBridge);assert.equal(repaired.recoveryNeeded,true);assert.equal(planner.inspect(plan.id).steps[0].jobId,child.id);assert.equal(r.home.findJob(old.id).retryJobId,child.id);assert.deepEqual(repaired.context.approvalRefs,[]);const count=r.home.listJobs('alex',99).length;r.home.recoverJobs();assert.equal(r.home.listJobs('alex',99).length,count);assert.equal(r.home.recoveryFaults.size,0);});
