test('review never refunds an exhausted gateway request limit',async t=>{
 const r=rig(t),x=await start(t,r,gatewayConfig({workerMaxRequests:1}),async()=>{throw Error('lost');});await gatewayCall(x);x.b.close();x.runs.end(x.run);r.home.updateJob('alex',x.job.id,{status:'failed'});const recovery=require('../lib/native-request-recovery').createRequestRecovery({home:r.home});recovery.apply(recovery.preview(x.job.id).token);const next=r.home.createJob('alex','Continue',{retryOf:x.job.id});r.home.updateJob('alex',next.id,require('../lib/job-retry').carry(r.home.findJob(x.job.id)));let calls=0;const y=await start(t,r,gatewayConfig({workerMaxRequests:1}),async()=>{calls++;return response(gatewayReply());},r.home.findJob(next.id));assert.equal((await gatewayCall(y,[{role:'user',content:'Continue'}])).status,400);assert.equal(calls,0);assert.equal(r.storage.open(r.home.findJob(next.id).nativeBridge).requests,1);
});
test('native history survives two verified failed retries before any new model submission',async t=>{
 const r=rig(t),x=await start(t,r);await x.call();x.b.close();x.runs.end(x.run);const original=r.home.findJob(x.job.id);r.home.updateJob('alex',original.id,{status:'failed'});
 let previous=r.home.findJob(original.id);for(let i=0;i<2;i++){const child=r.home.createJob('alex','Continue',{retryOf:previous.id});r.home.updateJob('alex',child.id,{...require('../lib/job-retry').carry(previous),status:'failed',retryLinkReady:true});r.home.updateJob('alex',previous.id,{status:'retried',retryJobId:child.id});previous=r.home.findJob(child.id);}
 const latest=previous;assert.equal(require('../lib/job-retry').historyOwner(r.home,latest,original.id).id,original.id);let generated=0;const y=await start(t,r,config(),async url=>{if(url.endsWith('generateContent'))generated++;return response(url.endsWith('countTokens')?{totalTokens:5}:reply());},latest);assert.equal(generated,0);assert.equal((await y.call([{role:'user',content:'Inspect before continuation'}])).status,200);assert.equal(generated,1);assert.equal(r.home.findJob(latest.id).tokenBudget.measuredInput,10);
});
test('multi-retry native history refuses orphaned, foreign, cyclic and reciprocal-link drift',t=>{
 const r=rig(t),owner=r.home.createJob('alex','Goal');r.home.updateJob('alex',owner.id,{status:'retried'});const middle=r.home.createJob('alex','Continue',{retryOf:owner.id});r.home.updateJob('alex',middle.id,{status:'retried',retryLinkReady:true});const leaf=r.home.createJob('alex','Continue',{retryOf:middle.id});r.home.updateJob('alex',leaf.id,{status:'failed',retryLinkReady:true});r.home.updateJob('alex',owner.id,{retryJobId:middle.id});r.home.updateJob('alex',middle.id,{retryJobId:leaf.id});const R=require('../lib/job-retry');assert.equal(R.historyOwner(r.home,r.home.findJob(leaf.id),owner.id).id,owner.id);assert.throws(()=>R.historyOwner(r.home,r.home.findJob(leaf.id),'missing'),/lineage/);r.home.updateJob('alex',middle.id,{retryJobId:'wrong'});assert.throws(()=>R.historyOwner(r.home,r.home.findJob(leaf.id),owner.id),/ownership/);r.home.updateJob('alex',middle.id,{retryJobId:leaf.id,retryOf:leaf.id});assert.throws(()=>R.historyOwner(r.home,r.home.findJob(leaf.id),owner.id),/ownership|cyclic/);assert.throws(()=>R.historyOwner(r.home,{...r.home.findJob(leaf.id),agent:'bob'},owner.id),/ownership/);
});
test('provider error diagnostics retain safe bounded status and do not expose bodies or credentials',async t=>{
 for(const status of [401,429,503]){const r=rig(t),x=await start(t,r,gatewayConfig(),async()=>new Response('PRIVATE_SECRET_RESPONSE',{status}));await gatewayCall(x);const d=x.b.failureDiagnostic();assert.equal(d.status,status);assert.equal(d.code,status===401?'authentication_refused':status===429?'rate_limited':'provider_http_failure');assert.ok(d.events.length<=20);assert.doesNotMatch(JSON.stringify(d),/PRIVATE_SECRET|PRIVATE_GATEWAY/);assert.deepEqual(r.home.findJob(x.job.id).nativeFailure,d);const j=r.storage.open(r.home.findJob(x.job.id).nativeBridge);assert.ok(j.pending);assert.equal(j.requests,1);d.events[0].code='changed';assert.notEqual(x.b.failureDiagnostic().events[0].code,'changed');}
});
test('worker failure prefers persisted broker cause over generic CLI error without replay',async t=>{
 const r=rig(t),bus=new(require('events').EventEmitter)(),oldFetch=global.fetch;let calls=0;global.fetch=async(url,opts)=>String(url).startsWith('http://127.0.0.1:')?oldFetch(url,opts):(calls++,new Response('SECRET_BODY',{status:429}));const native={brokerProtocol:1,preflight:async()=>({ok:true}),runTask:async(_a,_task,o)=>{await oldFetch(o.cfgOverride.workerBaseUrl+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+o.cfgOverride.workerApiKey},body:JSON.stringify({model:'space-bunny-free',messages:[{role:'user',content:'Goal'}]})});throw Error('Isolated runtime failed (opencode_task; unknown).');}};const workers=require('../lib/workers').createWorkers({home:r.home,bus,getCfg:()=>gatewayConfig({engine:'opencode'}),tools:{},gemini:{},opencode:native});try{const done=new Promise(resolve=>bus.once('job:done',resolve));const job=workers.dispatch('alex','Goal');await done;const saved=r.home.findJob(job.id);assert.match(saved.error,/rate_limited.*HTTP 429/);assert.equal(saved.nativeFailure.source,'host_model_broker');assert.equal(saved.nativeContinuity.requestOutcome,'unknown');assert.equal(calls,1);assert.doesNotMatch(JSON.stringify(saved),/SECRET_BODY/);}finally{workers.cancelAll();global.fetch=oldFetch;}
});
